// Contar pasos: cada vez que el programa hace una comparación o una suma, sumamos 1 a un contador
function sumarLista(lista) {
  let pasos = 0;
  let total = 0;
  for (let i = 0; i < lista.length; i++) {
    total += lista[i];   // una suma
    pasos++;
  }
  return { total, pasos };
}

function contarParesIguales(lista) {
  let pasos = 0;
  let iguales = 0;
  for (let i = 0; i < lista.length; i++) {
    for (let j = i + 1; j < lista.length; j++) {
      pasos++;           // una comparación por cada par
      if (lista[i] === lista[j]) iguales++;
    }
  }
  return { iguales, pasos };
}

function contarDuplicando(n) {
  let pasos = 0;
  for (let i = 1; i < n; i *= 2) {   // i se duplica en cada vuelta: 1, 2, 4, 8...
    pasos++;
  }
  return pasos;
}

for (const n of [10, 100, 1000, 10000]) {
  const lista = Array.from({ length: n }, (_, i) => i % 7);
  console.log(
    "n =", String(n).padStart(6),
    "| sumar:", String(sumarLista(lista).pasos).padStart(6),
    "| pares:", String(contarParesIguales(lista).pasos).padStart(10),
    "| duplicando:", contarDuplicando(n)
  );
}

// Medir tiempo real con n creciente. Los milisegundos dependen de tu máquina; lo que importa es el cociente entre una fila y la siguiente.
function sumar(lista) {
  let total = 0;
  for (let i = 0; i < lista.length; i++) total += lista[i];
  return total;
}
function paresIguales(lista) {
  let iguales = 0;
  for (let i = 0; i < lista.length; i++)
    for (let j = i + 1; j < lista.length; j++)
      if (lista[i] === lista[j]) iguales++;
  return iguales;
}
function milis(f, lista, repeticiones) {
  const t0 = performance.now();
  for (let k = 0; k < repeticiones; k++) f(lista);
  return (performance.now() - t0) / repeticiones;
}
// Calentamiento: el motor optimiza el código mientras lo corre, y las primeras vueltas son más lentas
milis(sumar, [1, 2, 3], 5000);
milis(paresIguales, Array.from({ length: 500 }, (_, i) => i), 20);

let antS = 0, antP = 0;
console.log("     n | sumar (µs) | cociente | pares (ms) | cociente");
for (const n of [1000, 2000, 4000, 8000]) {
  const lista = Array.from({ length: n }, (_, i) => i);
  const tS = milis(sumar, lista, 20000) * 1000;      // en microsegundos
  const tP = milis(paresIguales, lista, 1);
  console.log(
    String(n).padStart(6), "|",
    tS.toFixed(2).padStart(10), "|", (antS ? "x" + (tS / antS).toFixed(2) : "").padStart(8), "|",
    tP.toFixed(2).padStart(10), "|", antP ? "x" + (tP / antP).toFixed(2) : ""
  );
  antS = tS; antP = tP;
}

// Un depósito con N paquetes: buscar uno por su código de seguimiento
function crearPaquetes(n) {
  let semilla = 12345;
  const azar = () => (semilla = (semilla * 16807) % 2147483647);
  return Array.from({ length: n }, (_, i) => ({
    codigo: "AR" + String(azar()).padStart(10, "0") + String(i % 10),
    destino: "zona " + (i % 48),
  }));
}

// 1) Búsqueda en lista: mira uno por uno hasta encontrar
function buscarEnLista(paquetes, codigo) {
  let pasos = 0;
  for (const p of paquetes) {
    pasos++;
    if (p.codigo === codigo) return { p, pasos };
  }
  return { p: null, pasos };
}

const N = 100000;
const paquetes = crearPaquetes(N);

console.log("primero      :", buscarEnLista(paquetes, paquetes[0].codigo).pasos, "pasos");
console.log("del medio    :", buscarEnLista(paquetes, paquetes[N / 2].codigo).pasos, "pasos");
console.log("último       :", buscarEnLista(paquetes, paquetes[N - 1].codigo).pasos, "pasos");
console.log("no existe    :", buscarEnLista(paquetes, "AR0000000000X").pasos, "pasos");

// 2) Un índice: se arma UNA vez (cuesta N pasos) y después cada consulta es un salto
let t0 = performance.now();
const indice = new Map(paquetes.map(p => [p.codigo, p]));
const tIndice = performance.now() - t0;

// 1.000 consultas a paquetes repartidos de punta a punta de la lista
const consultas = Array.from({ length: 1000 }, (_, i) => paquetes[(i * 97) % N].codigo);

t0 = performance.now();
let pasosTotales = 0;
for (const c of consultas) pasosTotales += buscarEnLista(paquetes, c).pasos;
const tLista = performance.now() - t0;

t0 = performance.now();
let hallados = 0;
for (const c of consultas) if (indice.get(c)) hallados++;
const tMapa = performance.now() - t0;

console.log("pasos promedio por consulta en la lista:", Math.round(pasosTotales / consultas.length));
console.log("armar el índice:", tIndice.toFixed(1), "ms (una sola vez)");
console.log("1.000 consultas en la lista:", tLista.toFixed(1), "ms");
console.log("1.000 consultas en el índice:", tMapa.toFixed(3), "ms (hallados:", hallados + ")");
